import functools
import time
from typing import Tuple, Type

class RetryDecorator:
    """
    Decorador para reintentar una función hasta que se logre el éxito o se agoten los intentos permitidos.

    Parametros:
        max_attempts (int): Número máximo de intentos antes de relanzar la última excepción.
        delay (float): Tiempo en segundos entre cada intento fallido.
        exceptions (tuple): Tupla de tipos de excepciones que causa el fallo.
    """

    def __init__(self, max_attempts: int = 3, delay: float = 1.0, exceptions: Tuple[Type[Exception], ...] = (IOError, TimeoutError)):
        self.max_attempts = max_attempts
        self.delay = delay
        self.exceptions = exceptions

    def __call__(self, func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exception_type = None

            for attempt in range(self.max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except self.exceptions as e:
                    if attempt == self.max_attempts:
                        # Si agotamos los intentos, relanzamos la última excepción original
                        raise last_exception_type(e) from e
                    else:
                        last_exception_type = type(e)
                        print(f"Reintentando {attempt + 1}/{self.max_attempts} (Error: {e})")
                        time.sleep(self.delay)

            # Si llegamos aquí, significa que la función falló sin éxito tras todos los intentos
            raise last_exception_type(None) from None

        return wrapper

# Ejemplo de uso
if __name__ == "__main__":
    @RetryDecorator(max_attempts=3, delay=1.0, exceptions=(IOError, TimeoutError))
    def fetch_data(url: str):
        """Función que puede fallar por IOError o TimeoutError"""
        try:
            import requests
            response = requests.get(url, timeout=5)
            return response.json()
        except (IOError, TimeoutError) as e:
            raise RuntimeError(f"No se pudo conectar a la URL: {e}") from e

    # Simulación de ejecución
    try:
        result = fetch_data("http://example.com/data")
        print("Éxito:", result)
    except Exception as e:
        print("Fallo:", e)
```

